require_once __DIR__.'/../bootstrap/app.php';require_role('SUPER_ADMIN');$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$email=strtolower(trim($_POST['email']??''));if(!gmail_address($email))throw new RuntimeException('Use a valid Gmail address.');if(strlen($_POST['password']??'')<10)throw new RuntimeException('Password must have at least 10 characters.');db_execute("INSERT INTO USER_ACCOUNT (Email,PasswordHash,Role,Status,EmailVerifiedAt) VALUES (?,?,'RECEPTIONIST','ACTIVE',NOW())",'ss',[$email,password_hash($_POST['password'],PASSWORD_DEFAULT)]);audit('staff.created','USER_ACCOUNT',db()->insert_id,['role'=>'RECEPTIONIST']);set_flash('success','Receptionist account created.');redirect('admin/staff.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}$staff=db_all("SELECT UserID,Email,Status,CreatedAt,LastLoginAt FROM USER_ACCOUNT WHERE Role='RECEPTIONIST' ORDER BY CreatedAt DESC");$pageTitle='Reception staff';$pageSubtitle='Reception accounts are created only by super admin';include ROOT_PATH.'/includes/header.php';?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="split-layout"><div class="form-card"><h2 class="section-title">Create receptionist</h2><form method="post"><?=csrf_field()?><div class="form-group"><label for="email">Gmail address</label><input id="email" type="email" name="email" required></div><div class="form-group"><label for="password">Temporary password</label><input id="password" type="password" name="password" minlength="10" required></div><div class="form-actions"><button class="btn btn-primary">Create account</button></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Email</th><th scope="col">Status</th><th scope="col">Last login</th></tr></thead><tbody><?php foreach($staff as $s):?><tr><td><?=e($s['Email'])?></td><td><?=e($s['Status'])?></td><td><?=e($s['LastLoginAt']??'Never')?></td></tr><?php endforeach;?></tbody></table></div></div><?php include ROOT_PATH.'/includes/footer.php';?>
